        // Given an integer array of nums
        // return all the triplets 
        // where nums[i] + nums[j] + nums[k] == 0
        // And indices i, j, and k are all distinct.
        // output should not contain any duplicate triplets.
        // Can return the output and triplets in any order.

        /*
         * Example
         * nums = [-1, 0, 1, 2, -1, -4]
         * Ouput [[-1,-1,2],[-1,0,1]] (all of the arrays add up to 0)
         * 
         * nums = [0,1,1]
         * ouput = [] (none of the numbers would add up to zero)
         * 
         * Constaints:
         * 3 <= nums.length <= 3000
         * -10^5 <= nums[i] <= 10^5
         */
        public static List<List<int>> ThreeSum(int[] nums)
        {
            var threeSumList = new List<List<int>>();
            // Sort the array.
            for (int i = 0; i < nums.Length; i++)
            {
                for (int j = i + 1; j < nums.Length; j++)
                {
                    if (nums[i] > nums[j])
                    {
                        var temp = nums[i];
                        nums[i] = nums[j];
                        nums[j] = temp;
                    }
                }
            }


            // Need to go through 
            // [-4,-1,-1,0,1,2]
            // -2
            int l = 0;
            int r = nums.Length - 1;

            HashSet<string> alreadyAddedSet = new HashSet<string>();
            for (int i = 0; i < nums.Length; i++)
            {
                l = i + 1;
                r = nums.Length - 1;
                while (l < r)
                {
                    if (nums[i] + nums[l] + nums[r] < 0)
                    {
                        l++;
                    }
                    else if (nums[i] + nums[l] + nums[r] > 0)
                    {
                        r--;
                    }
                    else if (nums[i] + nums[l] + nums[r] == 0)
                    {
                        var toAdd = new List<int> { nums[l], nums[r], nums[i] };

                        // Unique hash key.
                        string hashKey = $"{nums[l]}{nums[r]}{nums[i]}";

                        if (!alreadyAddedSet.Contains(hashKey))
                        {
                            threeSumList.Add(toAdd);
                            alreadyAddedSet.Add(hashKey);
                        }
                        l++;
                        r--;
                    }
                }
            }

            return threeSumList;
        }

